namespace moon {
struct AntiAliasOptions {std::optional<std::uint32_t> color;int opacity=50;bool interior=false;int colorSource=0;}; // automatic, canvas, palette
inline int antiAliasLightness(std::uint32_t color){auto linear=[](int b){double v=b/255.0;return v<=.04045?v/12.92:std::pow((v+.055)/1.055,2.4);};double v=.2126*linear(color&255)+.7152*linear((color>>8)&255)+.0722*linear((color>>16)&255);return int(std::clamp(std::floor(255*(v<=.0031308?v*12.92:1.055*std::pow(v,1/2.4)-.055)+.5),0.0,255.0));}
// Exact legacy antiAliasSelection order is retained: composite samples see earlier painted intersections.
inline std::optional<std::vector<std::uint32_t>> antiAliasPixels(const std::vector<std::uint32_t>& input,int width,int height,const std::optional<SelectionMask>& selection,const AntiAliasOptions& options,const std::vector<std::uint32_t>& palette,const std::vector<std::uint32_t>& canvas,const std::function<std::uint32_t(int,int)>& sample,const std::function<void(std::size_t,std::uint32_t)>& write,const std::function<bool()>& cancelled){
 auto output=input;auto scope=[&](int x,int y){return x>=0&&y>=0&&x<width&&y<height&&(!selection||selectionContains(selection,x,y));};auto read=[&](int x,int y){return x>=0&&y>=0&&x<width&&y<height?input[std::size_t(y)*width+x]:0u;};
 int left=width,top=height,right=0,bottom=0;for(int y=0;y<height;++y){if(cancelled())return {};for(int x=0;x<width;++x)if(read(x,y)>>24){left=std::min(left,x);top=std::min(top,y);right=std::max(right,x+1);bottom=std::max(bottom,y+1);}}if(selection){left=selection->x;top=selection->y;right=left+selection->width;bottom=top+selection->height;}if(right<=left||bottom<=top)return output;
 struct Candidate{int index;std::uint32_t color;int rank;};auto outlines=[&](bool horizontal){std::vector<Candidate> candidates,clipped;std::unordered_map<int,std::size_t> lookup;int l=std::max(0,left-1),t=std::max(0,top-1),r=std::min(width,right+1),b=std::min(height,bottom+1);auto source=[&](int x,int y){return x>=l&&y>=t&&x<r&&y<b&&scope(x,y)&&(read(x,y)>>24);};for(int y=t;y<b;++y){if(cancelled())return candidates;for(int x=l;x<r;++x){if(!source(x,y))continue;bool boundary=false;for(int dy=-1;dy<=1;++dy)for(int dx=-1;dx<=1;++dx)if((dx||dy)&&!source(x+dx,y+dy))boundary=true;if(!boundary)continue;for(int d:{-1,1}){int dx=horizontal?d:0,dy=horizontal?0:d,tx=x+dx,ty=y+dy;if(tx<0||ty<0||tx>=width||ty>=height||source(tx,ty)||(read(tx,ty)>>24))continue;int index=ty*width+tx,rank=(-dy+1)*3-dx+1;auto found=lookup.find(index);if(found==lookup.end()){lookup[index]=candidates.size();candidates.push_back({index,read(x,y),rank});}else if(rank<candidates[found->second].rank)candidates[found->second]={index,read(x,y),rank};}}}if(selection){for(auto c:candidates)if(scope(c.index%width,c.index/width))clipped.push_back(c);if(!clipped.empty())return clipped;}return candidates;};
 struct Intersection {int index;std::uint32_t horizontal,vertical;};std::vector<Intersection> intersections;std::unordered_map<int,std::size_t> intersectionMap;auto set=[&](int index,std::uint32_t h,std::uint32_t v){auto found=intersectionMap.find(index);if(found==intersectionMap.end()){intersectionMap[index]=intersections.size();intersections.push_back({index,h,v});}else intersections[found->second]={index,h,v};};auto horizontal=outlines(true),vertical=outlines(false);std::unordered_map<int,std::uint32_t> vmap;for(auto c:vertical)vmap[c.index]=c.color;for(auto c:horizontal)if(scope(c.index%width,c.index/width)){auto v=vmap.find(c.index);if(v!=vmap.end())set(c.index,c.color,v->second);}
 if(options.interior){std::vector<int> region(input.size(),-1),order;struct Region{std::uint32_t color;int area;};std::vector<Region> regions;for(int y=std::max(0,top);y<std::min(height,bottom);++y){if(cancelled())return {};for(int x=std::max(0,left);x<std::min(width,right);++x){int start=y*width+x;if(!scope(x,y)||region[start]>=0||!(read(x,y)>>24))continue;int id=int(regions.size()),area=0;auto color=read(x,y);std::vector<int> queue{start};region[start]=id;while(!queue.empty()){if((area&127)==0&&cancelled())return {};int current=queue.back();queue.pop_back();order.push_back(current);++area;int cx=current%width,cy=current/width;for(auto offset:std::array<std::pair<int,int>,4>{{{-1,0},{1,0},{0,-1},{0,1}}}){int nx=cx+offset.first,ny=cy+offset.second;if(nx<left||ny<top||nx>=right||ny>=bottom||!scope(nx,ny))continue;int ni=ny*width+nx;if(region[ni]<0&&read(nx,ny)==color){region[ni]=id;queue.push_back(ni);}}}regions.push_back({color,area});}}
 std::vector<Candidate> h,v;std::unordered_map<int,std::size_t> hm,vm;auto add=[&](int tx,int ty,int si,bool horizontal){if(tx<left||ty<top||tx>=right||ty>=bottom||!scope(tx,ty))return;int ti=ty*width+tx,sr=region[si],tr=region[ti];if(sr<0||tr<0||sr==tr||regions[tr].area<regions[sr].area||(regions[tr].area==regions[sr].area&&tr<sr))return;auto& list=horizontal?h:v;auto& map=horizontal?hm:vm;auto it=map.find(ti);Candidate c{ti,regions[sr].color,0};if(it==map.end()){map[ti]=list.size();list.push_back(c);}else list[it->second]=c;};for(int si:order){int x=si%width,y=si/width;add(x-1,y,si,true);add(x+1,y,si,true);add(x,y-1,si,false);add(x,y+1,si,false);}for(auto c:h){auto it=vm.find(c.index);if(it!=vm.end())set(c.index,c.color,v[it->second].color);}}
 std::vector<std::uint32_t> canvasColors;std::unordered_map<std::uint32_t,bool> seen;for(auto color:canvas)if((color>>24)&&!seen.count(color)){seen[color]=true;canvasColors.push_back(color);}
 for(auto intersection:intersections){if(cancelled())return {};int x=intersection.index%width,y=intersection.index/width;auto target=output[intersection.index],first=intersection.horizontal,second=intersection.vertical;if(options.colorSource&& (target>>24)&&target!=first){second=first;first=target;}std::uint32_t automatic=first;const auto& colors=options.colorSource==2?palette:canvasColors;
 if(options.colorSource&&!colors.empty()){int a=antiAliasLightness(first),b=antiAliasLightness(second);double midpoint=(a+b)/2.0;bool have=false,intermediate=false;double best=0;for(auto color:colors)if((color>>24)&&color!=target){int light=antiAliasLightness(color);bool between=light>std::min(a,b)&&light<std::max(a,b);double distance=std::abs(light-midpoint);if(!have||(between&&!intermediate)||(between==intermediate&&distance<best)){have=true;intermediate=between;best=distance;automatic=color;}}if(!have)automatic=options.colorSource==2?colors.front():first;}
 else{struct Surround{std::uint32_t color;int count,distance,rank;};std::vector<Surround> nearby;std::unordered_map<std::uint32_t,std::size_t> indexes;int rank=0;for(int dy=-1;dy<=1;++dy)for(int dx=-1;dx<=1;++dx){if(!dx&&!dy)continue;int sx=x+dx,sy=y+dy;if(selection&&!selectionContains(selection,sx,sy))continue;auto color=sample(sx,sy);if(!(color>>24)||color==target)continue;auto found=indexes.find(color);if(found==indexes.end()){indexes[color]=nearby.size();nearby.push_back({color,1,std::abs(dx)+std::abs(dy),rank});}else ++nearby[found->second].count;++rank;}if(!nearby.empty()){auto best=nearby.front();for(auto c:nearby)if(c.count>best.count||(c.count==best.count&&(c.distance<best.distance||(c.distance==best.distance&&c.rank<best.rank))))best=c;automatic=best.color;}}
 auto color=options.color.value_or(options.colorSource?automatic:(automatic&0xffffff)|(std::uint32_t(std::floor((automatic>>24)*std::clamp(options.opacity,0,100)/100.0+.5))<<24));auto painted=(color>>24)?brushComposite(target,color,100):color;output[intersection.index]=painted;write(intersection.index,painted);
 }
 return cancelled()?std::optional<std::vector<std::uint32_t>>{}:std::optional<std::vector<std::uint32_t>>{std::move(output)};
}
}
